/** Every season on file for one player, archived teams included. */
export async function getPlayerCareer(slug: string): Promise<PlayerCareer> {
  const { data } = await api.get(`/stats/player/${encodeURIComponent(slug)}`)
  return data
}

export interface TeamRecord {
  league: string
  sport: string
  team_name?: string
  season?: string
  year?: number
  wins: number
  losses: number
  ties: number
}

export async function updateTeamRecord(record: TeamRecord): Promise<{ success: boolean; wins: number; losses: number; ties: number }> {
  const { data } = await api.put('/stats/team/record', record)
  return data
}

export async function uploadTeamStats(
  file: File,
  league: string,
  sport: string,
  season: string,
  year: number
): Promise<{ success: boolean; batting: number; pitching: number; fielding?: number; teams: number }> {
  const formData = new FormData()
  formData.append('file', file)
  formData.append('league', league)
  formData.append('sport', sport)
  formData.append('season', season)
  formData.append('year', String(year))

  const { data } = await api.post('/stats/upload', formData, {
    headers: {
      'Content-Type': 'multipart/form-data'
    }
  })
  
  return data
}
